def sum_of_divisors(n: int) -> int:
    """
    Return sum of all divisors of a number n.

    >>> sum_of_divisors(6)
    6
    """
    if n < 1 or n > 1000:
        raise ValueError('Input number must be in [1; 1000]')
    divisors = []
    for i in range(1, n + 1):
        if n % i == 0:
            divisors.append(i)
    return sum(divisors)


