def parse_nested_parens_reversed(paren_string: str) -> List[int]:
    """ This function behaves the same as the previous one but it uses Python's list comprehension to avoid the need for loops and built-in function count().

    >>> parse_nested_parens_reversed('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    depths = [len(group) for group in paren_string.split(" ")]
    return depths


def sum_nested_parens(depths: List[int]) -> int:
    return sum([depth + sum_nested_parens(depths[i:]) for i, depth in enumerate(depths)])


